// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address caller, uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 <= type(uint256).max - amount2);
        vm.assume(caller != address(0));
        vm.deal(caller, amount1 + amount2);

        vm.startPrank(caller);
        c.addToBalance{value: amount1}();
        c.addToBalance{value: amount2}();
        vm.stopPrank();

        uint256 expected = amount1 + amount2;
        uint256 actual = c.getBalance(caller);
        assertEq(actual, expected);
    }
}
